class PlaceOrderService:
    def __init__(self, orders, customers, events, uow):
        ...
    def place(self, cmd: PlaceOrder) -> OrderId:
        with self.uow:                                  # one transaction per use case
            customer = self.customers.of_id(cmd.customer_id)
            order = customer.place_order(cmd.items)     # the model decides
            self.orders.add(order)
            self.events.record_outbox(customer.pending_events)  # relay after commit
            return order.id
